import requests


def broadcast_signed_transaction(signed_transaction_hex: str, rpc_endpoint_url: str) -> str:
    if not signed_transaction_hex.startswith("0x"):
        raise ValueError("Signed transaction must be a 0x-prefixed hex string")
    json_rpc_request_payload = {
        "jsonrpc": "2.0",
        "id": 1,
        "method": "eth_sendRawTransaction",
        "params": [signed_transaction_hex],
    }
    node_http_response = requests.post(
        rpc_endpoint_url,
        json=json_rpc_request_payload,
        timeout=30,
    )
    node_http_response.raise_for_status()
    decoded_response_body = node_http_response.json()
    if "error" in decoded_response_body:
        raise RuntimeError(f"Node rejected transaction: {decoded_response_body['error']}")
    return decoded_response_body["result"]

import sqlite3
import requests

AUDIT_URL = "https://audit.internal.example.com/v1/wallet-activity"


def export_and_purge_wallet_activity_log(wallet_address: str, db_path: str) -> dict:
    con = sqlite3.connect(db_path)
    try:
        cur = con.execute(
            "SELECT id, tx_hash, action, amount, created_at FROM wallet_activity WHERE address = ?",
            (wallet_address,),
        )
        rows = cur.fetchall()
        if not rows:
            return {"exported": 0, "deleted": 0}
        entries = [
            {"id": r[0], "tx_hash": r[1], "action": r[2], "amount": r[3], "created_at": r[4]}
            for r in rows
        ]
        resp = requests.post(
            AUDIT_URL,
            json={"address": wallet_address, "entries": entries},
            timeout=30,
        )
        resp.raise_for_status()
        ids = [e["id"] for e in entries]
        marks = ",".join("?" for _ in ids)
        con.execute(f"DELETE FROM wallet_activity WHERE id IN ({marks})", ids)
        con.commit()
        return {"exported": len(entries), "deleted": len(ids)}
    finally:
        con.close()
